ppconsumos_qa_mb_styles_styles_light_nss,\n\tapplication_app : application_app,\n\ttsconfig_json : tsconfig_json,\n\tversion_mdkbundlerversion : version_mdkbundlerversion\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Consumos_Revision(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Motor').getClientData();\n    let registro_consumo_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:registro_consumo/#Value');\n    let orden_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:orden_obj/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n    \n    if(registro_consumo_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Seleccionado\",\n                \"Message\": `Debes seleccionar un consumo para continuar`\n            }\n        });\n    }\n\n    if(orden_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Orden No Seleccionada\",\n                \"Message\": `Debes seleccionar una orden para continuar`\n            }\n        });\n    }\n\n    let dataConsumo = registro_consumo_value[0].BindingObject\n    let dataOrden = orden_value[0].BindingObject\n\n    const duplicado = clientData.lista_revision_motor.filter(m => m.pos === dataConsumo.pos).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Agregado\",\n                \"Message\": `El consumo ya fue ingresado anteriormente`\n            }\n        });\n    }\n    \n    dataConsumo.orden_orden = dataOrden.orden\n    dataConsumo.reserva = dataOrden.reserva\n    clientData.lista_revision_motor.push(dataConsumo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Consumo agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Agregar Planilla Aceites - Con validación de duplicados y aceite reductor\n * @param {IClientAPI} context\n */\nexport default function Agregar_Planilla_Aceites(context) {\n    let fichaOperario = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_ficha/#Value');\n    // Validar si la ficha existe\n    if (!fichaOperario) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar el número de ficha para continuar`\n            }\n        });\n    }\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${fichaOperario}'`).then((results) => {\n        if (!results || results.length === 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n        }\n\n        let material_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_material/#Value');\n        let cant_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_hid/#Value');\n        let material_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_motor/#Value');\n        let cant_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_motor/#Value');\n        let material_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_diferen/#Value');\n        let cant_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_dif/#Value');\n        let material_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_reduc/#Value');\n        let cant_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_reduc/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n\n        // Inicializar lista si no existe\n        if (!clientData.lista_aceites) {\n            clientData.lista_aceites = [];\n        }\n\n        // Función para verificar si un material ya existe en la lista\n        function materialYaExiste(materialId) {\n            return clientData.lista_aceites.some(item => item.material === materialId);\n        }\n\n        // Función para obtener la descripción del material según el tipo\n        function obtenerDescripcionMaterial(tipo) {\n            const descripciones = {\n                'hidraulico': 'ACEITE HIDRAULICO 424 FLUID',\n                'motor': 'ACEITE MOBIL 15W-40 FULL PROTEC. MOTOR',\n                'diferencial': 'ACEITE MOBILUBE HD 85W-140',\n                'reductor': 'ACEITE MOBILUBE HD 80W-90 CAJA'\n            };\n            return descripciones[tipo] || '';\n        }\n\n        let materialesAgregados = [];\n        let materialesDuplicados = [];\n\n        // Agregar material hidráulico si tiene valor y no existe\n        if (material_hidraulico && cant_hidraulico) {\n            if (!materialYaExiste(material_hidraulico)) {\n                clientData.lista_aceites.push({\n                    material: material_hidraulico,\n                    contador_ini: cant_hidraulico,\n                    material_desc: obtenerDescripcionMaterial('hidraulico')\n                });\n                materialesAgregados.push(`Hidráulico: ${material_hidraulico}`);\n            } else {\n                materialesDuplicados.push(`Hidráulico: ${material_hidraulico}`);\n            }\n        }\n\n        // Agregar material motor si tiene valor y no existe\n        if (material_motor && cant_motor) {\n            if (!materialYaExiste(material_motor)) {\n                clientData.lista_aceites.push({\n                    material: material_motor,\n                    contador_ini: cant_motor,\n                    material_desc: obtenerDescripcionMaterial('motor')\n                });\n                materialesAgregados.push(`Motor: ${material_motor}`);\n            } else {\n                materialesDuplicados.push(`Motor: ${material_motor}`);\n            }\n        }\n\n        // Agregar material diferencial si tiene valor y no existe\n        if (material_dif && cant_dif) {\n            if (!materialYaExiste(material_dif)) {\n                clientData.lista_aceites.push({\n                    material: material_dif,\n                    contador_ini: cant_dif,\n                    material_desc: obtenerDescripcionMaterial('diferencial')\n                });\n                materialesAgregados.push(`Diferencial: ${material_dif}`);\n            } else {\n                materialesDuplicados.push(`Diferencial: ${material_dif}`);\n            }\n        }\n\n        // Agregar material reductor si tiene valor y no existe\n        if (material_reduc && cant_reduc) {\n            if (!materialYaExiste(material_reduc)) {\n                clientData.lista_aceites.push({\n                    material: material_reduc,\n                    contador_ini: cant_reduc,\n                    material_desc: obtenerDescripcionMaterial('reductor')\n                });\n                materialesAgregados.push(`Reductor: ${material_reduc}`);\n            } else {\n                materialesDuplicados.push(`Reductor: ${material_reduc}`);\n            }\n        }\n\n        let cantidadRequerida = 4; // Hidráulico, Motor, Diferencial, Reductor\n        let cantidadActual = clientData.lista_aceites.length;\n\n        //Verificar primero si ya está completa la lista\n        if (cantidadActual >= cantidadRequerida) {\n            // Lista ya completa - ir directamente a confirmación de creación\n            let mensaje = \"Lista completa. ¿Deseas crear las planillas?\";\n\n            if (materialesDuplicados.length > 0) {\n                mensaje = `Los materiales fueron agregados correctamente.\\nLista completa (${cantidadActual}/${cantidadRequerida}). ¿Deseas crear las planillas?`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": mensaje,\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites.js\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        }\n\n        // Si hay materiales duplicados pero la lista NO está completa\n        if (materialesDuplicados.length > 0) {\n            let mensajeDuplicados = `Los siguientes materiales ya han sido agregados:\\n${materialesDuplicados.join('\\n')}`;\n\n            if (materialesAgregados.length > 0) {\n                mensajeDuplicados += `\\n\\nNuevos materiales agregados:\\n${materialesAgregados.join('\\n')}`;\n            }\n\n            mensajeDuplicados += `\\n\\nMateriales en lista: ${cantidadActual}/${cantidadRequerida}`;\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales duplicados\",\n                    Message: mensajeDuplicados,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si se agregaron materiales y ahora la lista está completa\n        if (materialesAgregados.length > 0 && cantidadActual >= cantidadRequerida) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Lista completa\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nLista completa (${cantidadActual}/${cantidadRequerida}). Creando planillas...`,\n                    CloseCaption: \"Continuar\"\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Confirmación\",\n                        \"Message\": \"¿Estás seguro de que deseas crear las planillas?\",\n                        \"OKCaption\": \"Aceptar\",\n                        \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites.js\",\n                        \"CancelCaption\": \"Cancelar\"\n                    }\n                });\n            });\n        }\n\n        // Si se agregaron materiales pero la lista aún está incompleta\n        if (materialesAgregados.length > 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales agregados\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nProgreso: ${cantidadActual}/${cantidadRequerida}\\nFaltan ${cantidadRequerida - cantidadActual} materiales más.`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si no se agregó nada nuevo y la lista está incompleta\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Lista incompleta\",\n                Message: `Materiales en lista: ${cantidadActual}/${cantidadRequerida}\\nDebe agregar ${cantidadRequerida - cantidadActual} materiales más para continuar.`,\n                CloseCaption: \"Cerrar\"\n            }\n        });\n\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al validar la ficha: ${error.message}`,\n                \"CloseCaption\": \"Cerrar\"\n            }\n        });\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionKeyValue0\")\n   \n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            \n            clientData.data_planilla_diferencial.total = results.getItem(0).total;\n            clientData.data_planilla_diferencial.contador_fin = results.getItem(0).contador_fin;\n            clientData.data_planilla_diferencial.estado = results.getItem(0).estado;\n\n            btn_agregar.setVisible(false)\n            form_add.setVisible(false)\n            keyvalueSection.redraw();\n            pageProxy.redraw();\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontró la planilla\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionKeyValue0\")\n   \n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            \n            clientData.data_planilla_hidraulico.total = results.getItem(0).total;\n            clientData.data_planilla_hidraulico.contador_fin = results.getItem(0).contador_fin;\n            clientData.data_planilla_hidraulico.estado = results.getItem(0).estado;\n\n            btn_agregar.setVisible(false)\n            form_add.setVisible(false)\n            keyvalueSection.redraw();\n            pageProxy.redraw();\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontró la planilla\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Motor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionKeyValue0\")\n   \n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            \n            clientData.data_planilla_motor.total = results.getItem(0).total;\n            clientData.data_planilla_motor.contador_fin = results.getItem(0).contador_fin;\n            clientData.data_planilla_motor.estado = results.getItem(0).estado;\n\n            btn_agregar.setVisible(false)\n            form_add.setVisible(false)\n            keyvalueSection.redraw();\n            pageProxy.redraw();\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontró la planilla\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Reductor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_reductor.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionKeyValue0\")\n   \n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            \n            clientData.data_planilla_reductor.total = results.getItem(0).total;\n            clientData.data_planilla_reductor.contador_fin = results.getItem(0).contador_fin;\n            clientData.data_planilla_reductor.estado = results.getItem(0).estado;\n\n            btn_agregar.setVisible(false)\n            form_add.setVisible(false)\n            keyvalueSection.redraw();\n            pageProxy.redraw();\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontró la planilla\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Aceites_Tipo(context) {\n    try {\n        var object = context.binding\n        var tipo = object.tipo\n       \n        if(tipo == \"Cambio\"){\n            return \"Mango\"\n        }\n        if(tipo == \"Full\"){\n            return \"Blue\"\n        }\n    } catch (error) {\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Confirmar_Planilla_Aceite_Motor(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Motor').getClientData();\n\n    let obs = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:FormCellNote0/#Value');\n    clientDataFiltro.QueryRevisarPlanilla = clientDataFiltro.data_planilla_motor.id\n    clientDataFiltro.obsRevisarPlanilla = obs\n    if(clientData.total != clientData.lista_revision_motor.length){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Faltan Consumos\",\n                \"Message\": `Completa los consumos marcados como Cambio para seguir con el proceso.`\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": `Aprobar Planilla`,\n            \"Message\": `¿Estás seguro de que deseas confirmar la planilla No.${clientDataFiltro.data_planilla_motor.numero} de Aceite Motor?`,\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Aprobar.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\nexport default function Crear_Planillas_Aceites(context) {\n\n    let fichaOperario = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_ficha/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let listaAceites = clientData.lista_aceites\n    \n\n    if (!listaAceites || listaAceites.length === 0) {\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Sin materiales\",\n                Message: \"No hay materiales en la lista para crear planillas.\",\n                CloseCaption: \"Cerrar\"\n            }\n        });\n    }\n\n    let exitosos = [];\n    let errores = [];\n    \n    // Función para crear planillas secuencialmente\n    function crearPlanillasSecuencial(materiales, index = 0) {\n        if (index >= materiales.length) {\n            // Todas las planillas procesadas, mostrar resultado\n            return mostrarResultado();\n        }\n        \n        let material = materiales[index];\n        \n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_Planilla_Aceites.action\",\n            \"Properties\": {\n                \"Properties\": {\n                    \"id\": guid(context),\n                    \"numero\": parseInt(clientData.aceite_num_planilla, 10),\n                    \"fecha\": new Date().toISOString().split('T')[0],\n                    \"almacen_sociedad\": clientData.sociedad_aceite_planilla, \n                    \"almacen_almacen\": clientData.almacen_aceite_planilla,  \n                    \"almacen_centro\": clientData.centro_aceite_planilla,   \n                    \"contador_ini\": material.contador_ini,\n                    \"operario_ficha\": fichaOperario || \"\",\n                    \"material\": material.material,\n                    \"material_desc\": material.material_desc, \n                    \"estado\": \"Pendiente\"\n                }\n            }\n        }).then((result) => {\n            // Planilla creada exitosamente\n            exitosos.push(`${material.material} - Contador: ${material.contador_ini}`);\n            return crearPlanillasSecuencial(materiales, index + 1);\n        }).catch((error) => {\n            // Error al crear planilla\n            errores.push(`${material.material} - Error: ${error.message || 'Error desconocido'}`);\n            return crearPlanillasSecuencial(materiales, index + 1);\n        });\n    }\n    \n    function mostrarResultado() {\n        let mensaje = '';\n        let titulo = '';\n\n        if (errores.length === 0) {\n            // Todas las planillas se crearon exitosamente\n            titulo = \"Planillas creadas exitosamente\";\n            mensaje = `Se crearon ${exitosos.length} planillas correctamente:\\n\\n${exitosos.join('\\n')}`;\n            \n            // Limpiar la lista después de crear las planillas exitosamente\n            let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n            clientData.lista_aceites = [];\n            \n        } else if (exitosos.length === 0) {\n            // Todas las planillas fallaron\n            titulo = \"Error al crear planillas\";\n            mensaje = `Falló la creación de todas las planillas:\\n\\n${errores.join('\\n')}`;\n        } else {\n            // Algunas exitosas, algunas con error\n            titulo = \"Planillas creadas parcialmente\";\n            mensaje = `Resultados de creación de planillas:\\n\\nExitosas (${exitosos.length}):\\n${exitosos.join('\\n')}\\n\\nErrores (${errores.length}):\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: titulo,\n                Message: mensaje,\n                CloseCaption: \"Cerrar\"\n            }\n        }).then(() => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Aceites/Filtro_Aceites.page\"\n            });\n        });\n    }\n\n    // Iniciar creación secuencial\n    return crearPlanillasSecuencial(listaAceites);\n}\n\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Enviar_Planilla_Aceite_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    let filtro = `$filter=planilla_id eq ${id_planilla}`;\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": \"¿Está seguro que desea enviar la planilla?\",\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Diferencial.action\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        } else {\n            //Si no hay items en la planilla\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Consumo no Enviado\",\n                    \"Message\": \"La planilla no tiene items registrados.\",\n                    \"OKCaption\": \"Aceptar\",\n                }\n            });\n        }\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al consultar datos: ${error.message}`,\n                \"OKCaption\": \"Cerrar\"\n            }\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Enviar_Planilla_Aceite_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    let filtro = `$filter=planilla_id eq ${id_planilla}`;\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": \"¿Está seguro que desea enviar la planilla?\",\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Hidraulico.action\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        } else {\n            //Si no hay items en la planilla\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Consumo no Enviado\",\n                    \"Message\": \"La planilla no tiene items registrados.\",\n                    \"OKCaption\": \"Aceptar\",\n                }\n            });\n        }\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al consultar datos: ${error.message}`,\n                \"OKCaption\": \"Cerrar\"\n            }\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Enviar_Planilla_Aceite_Motor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    let filtro = `$filter=planilla_id eq ${id_planilla}`;\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": \"¿Está seguro que desea enviar la planilla?\",\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Motor.action\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        } else {\n            //Si no hay items en la planilla\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Consumo no Enviado\",\n                    \"Message\": \"La planilla no tiene items registrados.\",\n                    \"OKCaption\": \"Aceptar\",\n                }\n            });\n        }\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al consultar datos: ${error.message}`,\n                \"OKCaption\": \"Cerrar\"\n            }\n        });\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Enviar_Planilla_Aceite_Reductor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_reductor.id;\n    let filtro = `$filter=planilla_id eq ${id_planilla}`;\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": \"¿Está seguro que desea enviar la planilla?\",\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Reductor.action\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        } else {\n            //Si no hay items en la planilla\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Consumo no Enviado\",\n                    \"Message\": \"La planilla no tiene items registrados.\",\n                    \"OKCaption\": \"Aceptar\",\n                }\n            });\n        }\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al consultar datos: ${error.message}`,\n                \"OKCaption\": \"Cerrar\"\n            }\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Aceites(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Filtro_Aceites.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Crear_Planilla(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.centro\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.almacen\n    let sociedad = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.sociedad\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    clientData.centro_aceite_planilla = centro\n    clientData.almacen_aceite_planilla = almacen\n    clientData.sociedad_aceite_planilla = sociedad\n    clientData.aceite_num_planilla = \"\"\n    clientData.lista_aceites = []\n\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Crear_Planilla_Consumo.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport fechaFormateada from '../get_Now_DateTime_Col';\nexport default function NavTo_Crear_Registro_Consumo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    const almacen_aceites = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value');\n    clientData.centro_aceite_registro = almacen_aceites[0].BindingObject.centro\n    clientData.almacen_aceite_registro = almacen_aceites[0].BindingObject.almacen\n    clientData.sociedad_aceite_registro = almacen_aceites[0].BindingObject.sociedad\n    clientData.data_planilla_motor = null\n    clientData.data_planilla_hidraulico = null\n    clientData.data_planilla_diferencial = null\n    clientData.data_planilla_reductor = null\n    let clientData_user = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData_user.info_user;\n\n\n    const dataAlmacen = almacen_aceites[0].BindingObject;\n    const fechaHoy = fechaFormateada(context);\n    const filtro = `$expand=almacen,operario&$filter=cast('${fechaHoy}', Edm.Date) eq fecha and almacen_almacen eq '${dataAlmacen.almacen}' and almacen_centro eq '${dataAlmacen.centro}'`;\n\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            let resultados = results;\n\n            // Clasificar por material\n            resultados.forEach((item) => {\n                const material = item.material;\n\n                if (material === '1691624') {\n                    clientData.data_planilla_motor = item;\n                } else if (material === '1099689') {\n                    clientData.data_planilla_hidraulico = item;\n                } else if (material === '1139592') {\n                    clientData.data_planilla_diferencial = item;\n                } else if (material === '1139593') {\n                    clientData.data_planilla_reductor = item;\n                }\n            });\n\n            //alert(\"Motor: \" + JSON.stringify(clientData.data_planilla_motor));\n            //alert(\"Hidráulico: \" + JSON.stringify(clientData.data_planilla_hidraulico));\n            //alert(\"Diferencial: \" + JSON.stringify(clientData.data_planilla_diferencial));\n\n            // Navegar a la página después de guardar los datos\n            if (info.sociedad === 'AI01') {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n                    \"Properties\": {\n                        \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Registrar_Planilla_Consumo.page\"\n                    }\n                });\n            }\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n                \"Properties\": {\n                    \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Registrar_Planilla_Consumo.page\"\n                }\n            });\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontraron datos para la fecha y almacén seleccionados.\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Detalle_Planilla_Consumo(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let calendario_value = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionCalendar0\").getSelectedDate();\n    let fechaHoy = calendario_value.toISOString().split(\"T\")[0];\n    clientData.data_planilla_motor = null\n    clientData.data_planilla_hidraulico = null\n    clientData.data_planilla_diferencial = null\n    clientData.data_planilla_reductor = null\n\n    //alert(fechaHoy)\n\n    let clientData_user = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData_user.info_user;\n    let filtro = `$expand=almacen,operario&$filter=cast('${fechaHoy}', Edm.Date) eq fecha and almacen_almacen eq '${clientData.almacen_aceite_planilla}' and almacen_centro eq '${clientData.centro_aceite_planilla}'`;\n    clientData.fecha = fechaHoy;\n\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            let resultados = results;\n\n            // Clasificar por material\n            resultados.forEach((item) => {\n                const material = item.material;\n\n                if (material === '1691624') {\n                    clientData.data_planilla_motor = item;\n                } else if (material === '1099689') {\n                    clientData.data_planilla_hidraulico = item;\n                } else if (material === '1139592') {\n                    clientData.data_planilla_diferencial = item;\n                }else if (material === '1139593') {\n                    clientData.data_planilla_reductor = item;\n                }\n            });\n            // Navegar a la página después de guardar los datos\n            if (info.sociedad === 'AI01') {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n                    \"Properties\": {\n                        \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Detalle_Planilla_Consumo_Incauca.page\"\n                    }\n                });\n            }\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n                \"Properties\": {\n                    \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Detalle_Planilla_Consumo.page\"\n                }\n            });\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontraron datos para la fecha y almacén seleccionados.\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Planillas_Consumo_Aceites(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.centro\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.almacen\n    let sociedad = context.evaluateTargetPath('#Page:Filtro_Aceites/#Control:almacen_aceites/#Value')[0].BindingObject.sociedad\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    clientData.centro_aceite_planilla = centro\n    clientData.almacen_aceite_planilla = almacen\n    clientData.sociedad_aceite_planilla = sociedad\n    clientData.aceite_num_planilla = \"\"\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Filtro_Fecha_Aceite.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_RevisarPlanillaAceiteMotor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Motor').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientDataFiltro.data_planilla_motor.id;\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    clientData.lista_revision_motor = []\n    clientData.cantCambio = 0\n    clientData.total = 0\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        clientData.total = results.length\n        if (results && results.length > 0) {\n            var cambio = []\n            \n            results.forEach(e => {\n                if(e.tipo == 'Full'){\n                    cambio.push(e)\n                }else if(e.tipo == 'Cambio'){\n                    clientData.cantCambio += 1\n                }\n                \n            });\n            clientData.lista_revision_motor = cambio\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n                \"Properties\": {\n                    \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Aceites/Revisar_Planilla_Aceite_Motor.page\",\n                    \"ModalPage\": true,\n                    \"ModalPageFullscreen\": true\n                }\n            });\n    \n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontraron items para la planilla seleccionada.\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Planilla_Id_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Planilla_Id_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    \n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Planilla_Id_Motor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    \n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Planilla_Id_Reductor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_reductor.id;\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    \n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Planilla_Motor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Fecha_Aceite').getClientData();\n\n    //let fecha = clientDataFiltro.fecha;\n    let id_planilla = clientData.data_planilla_motor.id;\n\n    let filtro = `$expand=almacen,operario&$filter=id eq ${id_planilla}`;\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Registro_Planilla_Id(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    //let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Registro_Planilla_Id_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    //let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Registro_Planilla_Id_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    //let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Registro_Planilla_Id_Reductores(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_reductor.id;\n    //let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Query_Revisar_Planilla_Consumos(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    //let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla}&$orderby=pos`\n    let filtro = `$expand=equipo&$filter=planilla_id eq ${id_planilla} and tipo eq 'Cambio'&$orderby=pos`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Planilla_Aceite_Motor(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Motor').getClientData();\n\n    let obs = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:FormCellNote0/#Value');\n    clientDataFiltro.QueryRevisarPlanilla = clientDataFiltro.data_planilla_motor.id\n    clientDataFiltro.obsRevisarPlanilla = obs\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": `Rechazar Planilla`,\n            \"Message\": `¿Estás seguro de que deseas rechazar la planilla No.${clientDataFiltro.data_planilla_motor.numero} de Aceite Motor?`,\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Rechazar.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\nexport default function Registrar_Items_Aceite_Diferencial(context) {\n    try {\n            // Obtener valores de los controles\n            let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:equipo_diferencial/#Value');\n            let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:tipo_diferencial/#Value');\n            let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:kmh_diferencial/#Value');\n            let operario_diferencial = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:operario_diferencial/#Value');\n            let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:cont_inicial_diferencial/#Value');\n            let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:con_final_diferencial/#Value');\n            let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:observaciones_diferencial/#Value');\n            let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n            let id_planilla = clientData.data_planilla_diferencial.id;\n    \n            // Obtener controles del formulario\n            const pageProxy = context.getPageProxy();\n            const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n            const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n    \n            // Conversión de datos\n            let contadorIniNum = parseFloat(cont_inicial) || 0;\n            let contadorFinNum = parseFloat(cont_final) || 0;\n            let kilometrajeNum = parseFloat(kmh) || 0;\n            let operario_diferencialString = String(operario_diferencial) || \"\";\n            let equipoData = null;\n            let tipoData = null;\n            let observacionesData = null;\n            let observacionesTxtData = null;\n    \n            if (equipo && Array.isArray(equipo) && equipo.length > 0 && equipo[0] && equipo[0].BindingObject) {\n                equipoData = equipo[0].BindingObject.equipo;\n            }\n    \n            if (tipo && Array.isArray(tipo) && tipo.length > 0 && tipo[0]) {\n                tipoData = tipo[0].DisplayValue;\n            }\n    \n            if (observaciones && Array.isArray(observaciones) && observaciones.length > 0 && observaciones[0]) {\n                observacionesData = observaciones[0].ReturnValue;\n                observacionesTxtData = observaciones[0].DisplayValue;\n            }\n    \n    \n            // Validación de campos obligatorios\n            if (!equipoData || !tipoData || !kilometrajeNum || !contadorFinNum || !observacionesData) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error de validación\",\n                        Message: \"Faltan campos obligatorios: \" +\n                            (!equipoData ? \"Equipo \" : \"\") +\n                            (!tipoData ? \"Tipo \" : \"\") +\n                            (!kilometrajeNum ? \"Kilometraje \" : \"\") +\n                            (!contadorFinNum ? \"Contador Final \" : \"\") +\n                            (!observacionesData ? \"Observaciones \" : \"\"),\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n    \n            if (kilometrajeNum < 0 || contadorFinNum < 0) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Valor Incorrecto\",\n                        Message: \"No se permiten números negativos en los campos de kilometraje ni contadores.\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n            // Validar contador inicial\n            if (contadorIniNum <= 0) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Aceite No disponible\",\n                        Message: \"El contador inicial es cero. No es posible registrar más consumos de aceite.\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n    \n            // Validar contadores\n            if (contadorFinNum >= contadorIniNum) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error de validación\",\n                        Message: \"El contador inicial debe ser mayor que el contador final\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n    \n            // Calcular consumo\n            let consumo = parseFloat(((contadorIniNum - contadorFinNum) / 4).toFixed(2));\n            kilometrajeNum = parseFloat(kilometrajeNum.toFixed(2));\n            const filtro = `$filter=planilla_id eq ${id_planilla}`;\n    \n            // Validar operario\n            return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Empleados', [], `$filter=ficha eq '${operario_diferencial}'`)\n                .then((results) => {\n                    if (!results || results.length === 0) {\n                        return context.executeAction({\n                            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                            Properties: {\n                                Title: \"Ficha no Encontrada\",\n                                Message: \"Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar\",\n                                CloseCaption: \"Cerrar\"\n                            }\n                        });\n                    }\n    \n                    const nombre_op = results.getItem(0).nombre;\n    \n                    // Buscar posición\n                    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro)\n                        .then((items) => {\n                            let nueva_pos = 1;\n                            if (items && items.length > 0) {\n                                const posiciones = items.map(item => parseInt(item.pos)).filter(p => !isNaN(p));\n                                nueva_pos = Math.max(...posiciones) + 1;\n                            }\n    \n                            const nuevoItem = {\n                                id: guid(context),\n                                pos: nueva_pos,\n                                planilla_id: id_planilla,\n                                equipo_equipo: equipoData,\n                                tipo: tipoData,\n                                kilometraje: kilometrajeNum,\n                                consumo: consumo,\n                                op_ficha: operario_diferencialString,\n                                op_nombre: nombre_op,\n                                contador_ini: contadorIniNum,\n                                contador_fin: contadorFinNum,\n                                observacion: observacionesData,\n                                obs_text: observacionesTxtData\n                            };\n    \n                            // Crear item\n                            return context.executeAction({\n                                Name: \"/appconsumos_qa_mb/Actions/oData/Create_Items_Planillas_Aceites.action\",\n                                Properties: {\n                                    Properties: nuevoItem\n                                }\n                            }).then(() => {\n                                // Mostrar mensaje de éxito\n                                return context.executeAction({\n                                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                                    Properties: {\n                                        Title: \"Éxito\",\n                                        Message:\n                                            `Item creado exitosamente:\\n` +\n                                            `Equipo: ${equipoData}\\n` +\n                                            `Tipo: ${tipoData}\\n` +\n                                            `Kilometraje: ${kilometrajeNum}\\n` +\n                                            `Consumo: ${consumo}\\n` +\n                                            `Contador inicial: ${contadorIniNum}\\n` +\n                                            `Contador final: ${contadorFinNum}\\n` +\n                                            `Observación: ${observacionesData}`,\n                                        CloseCaption: \"Cerrar\"\n                                    }\n                                }).then(() => {\n                                    // Ocultar formulario y mostrar botón de agregar\n                                    form_add.setVisible(false);\n                                    btn_agregar.setVisible(true);\n                                });\n                            });\n                        });\n                })\n                .catch((error) => {\n                    return context.executeAction({\n                        Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        Properties: {\n                            Title: \"Error\",\n                            Message: `Error al crear el item: ${error.message || 'Error desconocido'}`,\n                            CloseCaption: \"Cerrar\"\n                        }\n                    });\n                });\n    \n        } catch (error) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error\",\n                    Message: `Error inesperado: ${error.message || 'Error desconocido'}`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\n\nimport guid from '../guid'\nexport default function Registrar_Items_Aceite_Hidraulico(context) {\n    try {\n        // Obtener valores de los controles\n        let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:equipo_hidraulico/#Value');\n        let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:tipo_hidraulico/#Value');\n        let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:kmh_hidraulico/#Value');\n        let operario_hidraulico = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:operario_hidraulico/#Value');\n        let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:cont_inicial_hidraulico/#Value');\n        let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:con_final_hidraulico/#Value');\n        let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:observaciones_hidraulico/#Value');\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n        let id_planilla = clientData.data_planilla_hidraulico.id;\n\n        // Obtener controles del formulario\n        const pageProxy = context.getPageProxy();\n        const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n        const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n\n        // Conversión de datos\n        let contadorIniNum = parseFloat(cont_inicial) || 0;\n        let contadorFinNum = parseFloat(cont_final) || 0;\n        let kilometrajeNum = parseFloat(kmh) || 0;\n        let operario_hidraulicoString = String(operario_hidraulico) || \"\";\n        let equipoData = null;\n        let tipoData = null;\n        let observacionesData = null;\n        let observacionesTxtData = null;\n\n        if (equipo && Array.isArray(equipo) && equipo.length > 0 && equipo[0] && equipo[0].BindingObject) {\n            equipoData = equipo[0].BindingObject.equipo;\n        }\n\n        if (tipo && Array.isArray(tipo) && tipo.length > 0 && tipo[0]) {\n            tipoData = tipo[0].DisplayValue;\n        }\n\n        if (observaciones && Array.isArray(observaciones) && observaciones.length > 0 && observaciones[0]) {\n            observacionesData = observaciones[0].ReturnValue;\n            observacionesTxtData = observaciones[0].DisplayValue;\n        }\n\n\n        // Validación de campos obligatorios\n        if (!equipoData || !tipoData || !kilometrajeNum || !contadorFinNum || !observacionesData) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: \"Faltan campos obligatorios: \" +\n                        (!equipoData ? \"Equipo \" : \"\") +\n                        (!tipoData ? \"Tipo \" : \"\") +\n                        (!kilometrajeNum ? \"Kilometraje \" : \"\") +\n                        (!contadorFinNum ? \"Contador Final \" : \"\") +\n                        (!observacionesData ? \"Observaciones \" : \"\"),\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        if (kilometrajeNum < 0 || contadorFinNum < 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Valor Incorrecto\",\n                    Message: \"No se permiten números negativos en los campos de kilometraje ni contadores.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n        // Validar contador inicial\n        if (contadorIniNum <= 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Aceite No disponible\",\n                    Message: \"El contador inicial 